T.RegisterBuild({
    id = "PALADIN_SOLO", class = "PALADIN", short = "solo",
    name = "Protection: Solo Leveling",
    leveling = "Leveling_Tank", endgame = "PROT_DEEP",
    stage = "leveling", role = "tank", mode = "solo",
